def trans(p,k,ref):
 r,c=p
 if ref:c=-c
 for _ in range(k): r,c=c,-r
 return r,c
def forms(T):
 out=[]
 for ref in [False,True]:
  for k in range(4):
   pts=[trans(p,k,ref) for p in T]
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   out.append({(r-mr,c-mc) for r,c in pts})
 return out
